import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"14、【大有】 乾下离上","description":"温公易说 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"温公易说 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/wengong/015.md","filePath":"zh/classics/wengong/015.md"}'),n={name:"zh/classics/wengong/015.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><h3 id="彖曰-大有-柔得尊位-大中而上下应之-曰大有。其德刚健而文明-应乎天而时行-是以元亨。" tabindex="-1">彖曰：大有，柔得尊位，大中而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。 <a class="header-anchor" href="#彖曰-大有-柔得尊位-大中而上下应之-曰大有。其德刚健而文明-应乎天而时行-是以元亨。" aria-label="Permalink to “彖曰：大有，柔得尊位，大中而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。”">​</a></h3><p>大有者，何？富有之谓也。天子富有天下，诸侯富有其国，大夫富有其家。非得大有之道，乌能得其下乎？然则大有何？以柔为主。夫为人上者，言而人莫敢违也，动而人莫敢逆也，故戒之在刚也。夫上之所以能有下者，得其心也。得其心者，能以恩信结之也。故大有以柔中为主也。柔而不明，则前有谗而弗见，后有贼而不知。明而不健，则知善而不能举，知恶而不能去。二者皆乱亡之端也。明以烛之，健以决之，居不失中行，不失时，然后能保有其众而元亨也。然则大有何以上明而下健？曰：明胜于健，则赏不失功，罚不失罪。健胜于明，则反之。此大有所以当明也。</p><h3 id="象曰-火在天上-大有。君子以遏恶扬善-顺天休命。" tabindex="-1">象曰：火在天上，大有。君子以遏恶扬善，顺天休命。 <a class="header-anchor" href="#象曰-火在天上-大有。君子以遏恶扬善-顺天休命。" aria-label="Permalink to “象曰：火在天上，大有。君子以遏恶扬善，顺天休命。”">​</a></h3><p>火在天上，明之至也。至明则善恶无所遗矣。善则举之，恶则抑之。上之职也。明而能健，庆赏刑威，得其当然。后能保有四方，所以顺天美命也。</p><h3 id="初九-无交害-匪咎-艰则无咎-象曰-大有初九-无交害也。" tabindex="-1">初九：无交害，匪咎，艰则无咎 象曰：大有初九，无交害也。 <a class="header-anchor" href="#初九-无交害-匪咎-艰则无咎-象曰-大有初九-无交害也。" aria-label="Permalink to “初九：无交害，匪咎，艰则无咎 象曰：大有初九，无交害也。”">​</a></h3><h3 id="九二-大车以载-有攸往-无咎-象曰-大车以载-积中不败也。" tabindex="-1">九二：大车以载，有攸往，无咎 象曰：大车以载，积中不败也。 <a class="header-anchor" href="#九二-大车以载-有攸往-无咎-象曰-大车以载-积中不败也。" aria-label="Permalink to “九二：大车以载，有攸往，无咎 象曰：大车以载，积中不败也。”">​</a></h3><h3 id="九三-公用亨于天子-小人弗克-象曰-公用亨于天子-小人害也。" tabindex="-1">九三：公用亨于天子，小人弗克 象曰：公用亨于天子，小人害也。 <a class="header-anchor" href="#九三-公用亨于天子-小人弗克-象曰-公用亨于天子-小人害也。" aria-label="Permalink to “九三：公用亨于天子，小人弗克 象曰：公用亨于天子，小人害也。”">​</a></h3><h3 id="九四-匪其彭-无咎-象曰-匪其彭-无咎-明辨晰也。" tabindex="-1">九四：匪其彭，无咎 象曰：匪其彭，无咎，明辨晰也。 <a class="header-anchor" href="#九四-匪其彭-无咎-象曰-匪其彭-无咎-明辨晰也。" aria-label="Permalink to “九四：匪其彭，无咎 象曰：匪其彭，无咎，明辨晰也。”">​</a></h3><h3 id="六五-厥孚交如-威如-吉-象曰-厥孚交如-信以发志也。威如之吉-易而无备也。" tabindex="-1">六五：厥孚交如，威如，吉 象曰：厥孚交如，信以发志也。威如之吉，易而无备也。 <a class="header-anchor" href="#六五-厥孚交如-威如-吉-象曰-厥孚交如-信以发志也。威如之吉-易而无备也。" aria-label="Permalink to “六五：厥孚交如，威如，吉 象曰：厥孚交如，信以发志也。威如之吉，易而无备也。”">​</a></h3><p>六五柔得尊位，大中而上下应之，故曰厥孚交如。言孚发于中而应之者，交至也。夫以柔德而主众刚，推诚任物，易而无备。所可戒者，在于无威。故曰威如吉。此圣人所以儆戒人君，优游不暴，柔而不立者也。为人君者，刚而不暴，柔而不可犯，此所以为皇极之道。</p><h3 id="上九-自天佑之-吉-无不利-象曰-大有上吉-自天佑也。" tabindex="-1">上九：自天佑之，吉，无不利 象曰：大有上吉，自天佑也。 <a class="header-anchor" href="#上九-自天佑之-吉-无不利-象曰-大有上吉-自天佑也。" aria-label="Permalink to “上九：自天佑之，吉，无不利 象曰：大有上吉，自天佑也。”">​</a></h3>',12)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
